import { homedir } from 'node:os'
import { join } from 'node:path'
import { readOptional } from '../workspace-files'

export type InstructionFile = {
  /** Absolute path, named in the prompt so the model knows where a rule came from. */
  path: string
  text: string
}

/**
 * The instruction files the own loop reads, global first and workspace last
 * so the workspace's words sit nearest the task. CLAUDE.md is Claude Code's
 * name, AGENTS.md the cross-tool one; both levels take both. An applied rule
 * bundle lives inside one of these as an ordinary block of text, so a bundle
 * reaches wherever these files already do.
 */
export function instructionFilePaths(cwd: string, home = homedir()): string[] {
  return [
    join(home, '.claude', 'CLAUDE.md'),
    join(home, '.claude', 'AGENTS.md'),
    join(home, '.codex', 'AGENTS.md'),
    join(home, 'AGENTS.md'),
    join(cwd, 'CLAUDE.md'),
    join(cwd, 'AGENTS.md'),
  ]
}

/** Every instruction file that exists and says something, in prompt order. */
export async function readInstructionFiles(cwd: string, home = homedir()): Promise<InstructionFile[]> {
  const files: InstructionFile[] = []
  for (const path of instructionFilePaths(cwd, home)) {
    const text = await readOptional(path)
    if (text?.trim()) files.push({ path, text })
  }
  return files
}

/**
 * Told once, before the files: an instruction file may add a rule of its own
 * — an applied bundle among them — but it never stands above what the model
 * was already told. Where the two disagree the rule already given holds, and
 * the model says in its reply which rule from the file it set aside.
 */
export const CLASH_WITH_CORE =
  'An instruction file below may add a rule of its own, including one an applied bundle added. Where it contradicts a rule already given above, the rule already given holds; say in your reply which rule from the file you set aside.'

/** Every instruction file as one block of the prompt, the clash note first so what follows reads as an addition, never a replacement. */
export function instructionsText(files: InstructionFile[]): string {
  return [CLASH_WITH_CORE, ...files.map((file) => `\n# Instructions from ${file.path}\n\n${file.text}`)].join('\n')
}

/** Every mode but the blind planner: a bundle describes how code is written, and the planner never sees code, same as it never sees memories. */
export const wantsInstructions = (mode: string): boolean => mode !== 'plan'

/**
 * The workspace's and the person's instruction files, joined after a phase's
 * own prompt exactly where a chat already joins them — the same join an
 * applied bundle rides in on, since a bundle is nothing but a block of text
 * inside one of these files. Nothing is added unless one of the files holds
 * something: a workspace that never wrote a bundle into them carries none.
 */
export async function withInstructionFiles(mode: string, systemPrompt: string, cwd: string, home: string = homedir()): Promise<string> {
  if (!wantsInstructions(mode)) return systemPrompt
  const files = await readInstructionFiles(cwd, home)
  return files.length > 0 ? `${systemPrompt}\n${instructionsText(files)}` : systemPrompt
}

import { homedir } from 'node:os'
import { join } from 'node:path'
import { readOptional } from '../workspace-files'
import { projectMemoryDir } from './memories'

/**
 * Memories as a session start uses them: every session but the blind feature
 * planner begins with the project's notes already in hand, the index only, a
 * note's body read on demand when the work touches it. Read fresh from disk;
 * a memory is a handful of short files, never worth a generated-context build
 * like the repo map or the docs map. The person's own notes live inside their
 * instruction file instead of a folder of their own, so they ride along
 * wherever instruction files join a prompt rather than being read here.
 */

/** The modes that start with memories: everything but the blind planner, which stays exactly as blind to them as to the rest of the project. */
export const wantsMemories = (mode: string): boolean => mode !== 'plan'

export type MemorySources = { project: string | undefined }

/** The project's index (`MEMORY.md`), left out when there is nothing in it. */
export async function readMemorySources(cwd: string, home: string = homedir()): Promise<MemorySources> {
  const index = await readOptional(join(projectMemoryDir(cwd, home), 'MEMORY.md'))
  return { project: index?.trim() || undefined }
}

/** The project's notes as they go into a system prompt: one line each, a note's body read with Read when the work at hand touches it. */
export function memorySection(sources: MemorySources): string | undefined {
  if (!sources.project) return undefined
  return [
    '## What is already known',
    '',
    "Notes kept from earlier sessions. Open a note's file with Read when the work at hand touches it. A memory written this session is said in the chat as it happens, not repeated here.",
    '',
    'Project notes:',
    '',
    sources.project,
  ].join('\n')
}

/**
 * The system prompt a session of this mode starts with, the project's memory
 * index appended when the mode wants it. For the blind planner the prompt is
 * returned untouched and nothing is read.
 */
export async function withMemories(mode: string, systemPrompt: string, cwd: string, home: string = homedir()): Promise<string> {
  if (!wantsMemories(mode)) return systemPrompt
  const section = memorySection(await readMemorySources(cwd, home))
  return section ? `${systemPrompt}\n\n${section}` : systemPrompt
}

/**
 * The project's notes, for the Claude engine's own default chat prompt: its
 * own CLAUDE.md loading leaves out the project index (not a setting source)
 * and its auto-memory tool is off, so it reaches the prompt no other way. The
 * person's own notes live inside their instruction file and reach this chat
 * the same way they reach every other mode's, through the instruction files
 * joined alongside this section (see `session-engines.ts`).
 */
export async function chatMemorySection(cwd: string, home: string = homedir()): Promise<string | undefined> {
  return memorySection(await readMemorySources(cwd, home))
}

import type { Limits } from '../cleanup/oversized'
import { DocsMapContract } from '../docs-map/entry'
import { BLIND_PLAN_TOOLS, blindPlanPrompt, blindPlanScope } from '../phases/blind-plan'
import { CLEANUP_TOOLS, cleanupPrompt, cleanupScope } from '../phases/cleanup'
import { CODE_PLAN_TOOLS, codePlanPrompt } from '../phases/code-plan'
import { DOCS_EVALUATION_TOOLS, docsEvaluationPrompt, docsEvaluationScope } from '../phases/docs-evaluation'
import { DOCS_MAP_TOOLS, docsMapPrompt, docsMapScope } from '../phases/docs-map'
import { FILE_DECISIONS_TOOLS, fileDecisionsPrompt, fileDecisionsScope } from '../phases/file-decisions'
import { IMPLEMENT_TOOLS, implementPrompt } from '../phases/implement'
import { RECONCILE_TOOLS, reconcilePrompt, reconcileScope } from '../phases/reconcile'
import { ScenarioContextContract } from '../phases/scenario-context'
import { ScopeGuard, readableIn } from '../phases/scope-guard'
import { SpecContract } from '../phases/spec-model'
import { TaskBoardGuard } from '../openai-session/tools/task-board'
import type { VerifyRule } from '../phases/verification'
import { composeHooks, type SessionHooks } from './hooks'
import type { SessionRecord } from './session-manager'

/** What a session's mode dictates, independent of engine: hooks, prompt, tool set, and the files a search may hand back. */
export type ModeSetup = { hooks?: SessionHooks; systemPrompt?: string; toolNames?: string[]; readable?: (relPath: string) => boolean }

/** What the modes read from the workspace and its settings, and the maps a prompt carries, built when behind. */
export type ModeContext = {
  workspaceRoot: string
  verifyRules(): VerifyRule[]
  /** Docs the blind planner must not see, so neither the map nor the evaluation may describe them. */
  planIgnore(): string[]
  cleanupLimits(): Limits
  withMap(record: SessionRecord, systemPrompt: string): Promise<string>
  withDocs(record: SessionRecord, systemPrompt: string): Promise<string>
  /** The project's memory index, for every mode but the blind planner. */
  withMemories(record: SessionRecord, systemPrompt: string): Promise<string>
  /** The workspace's and the person's instruction files — an applied bundle rule among them — for every mode but the blind planner. */
  withInstructions(record: SessionRecord, systemPrompt: string): Promise<string>
}

export async function modeSetup(record: SessionRecord, ctx: ModeContext): Promise<ModeSetup> {
  const { workspaceRoot } = ctx
  // A chat may write a spec when asked to, held to the contract like the planner's.
  const chat = { hooks: new SpecContract(workspaceRoot) }
  if (record.access === 'full') return chat
  switch (record.mode) {
    case 'chat':
      return chat
    case 'implement': {
      if (!record.feature) throw new Error('An implement session needs a feature name')
      return {
        // The user's answers amend the task's rules, held to the contract like the planner's writes.
        hooks: composeHooks(new TaskBoardGuard(workspaceRoot, record.feature), new SpecContract(workspaceRoot)),
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, implementPrompt(record.feature, workspaceRoot, ctx.verifyRules())))),
        toolNames: IMPLEMENT_TOOLS,
      }
    }
    case 'plan': {
      if (!record.feature) throw new Error('A plan session needs a feature name')
      const scope = blindPlanScope(record.feature, ctx.planIgnore())
      return {
        // The contract answers on the write that broke it, so the planner fixes the spec in the same turn.
        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
        systemPrompt: await ctx.withDocs(record, blindPlanPrompt(record.feature, workspaceRoot)),
        toolNames: BLIND_PLAN_TOOLS,
        readable: readableIn(scope),
      }
    }
    case 'code-plan':
      // Read-only by its tool set: nothing to scope, and the build happens once the plan is approved.
      return {
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, await ctx.withDocs(record, codePlanPrompt(workspaceRoot))))),
        toolNames: CODE_PLAN_TOOLS,
      }
    case 'docs': {
      const scope = docsEvaluationScope(ctx.planIgnore())
      return {
        hooks: new ScopeGuard(workspaceRoot, scope),
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withDocs(record, docsEvaluationPrompt(workspaceRoot)))),
        toolNames: DOCS_EVALUATION_TOOLS,
        readable: readableIn(scope),
      }
    }
    case 'file-decisions': {
      const scope = fileDecisionsScope(ctx.planIgnore())
      return {
        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withDocs(record, fileDecisionsPrompt(workspaceRoot)))),
        toolNames: FILE_DECISIONS_TOOLS,
        readable: readableIn(scope),
      }
    }
    case 'docs-map': {
      return {
        // The entry contract answers on the write that broke it, so a bad anchor never reaches a planner's prompt.
        hooks: composeHooks(new ScopeGuard(workspaceRoot, docsMapScope(record.files ?? [])), new DocsMapContract(workspaceRoot)),
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, docsMapPrompt(workspaceRoot))),
        toolNames: DOCS_MAP_TOOLS,
      }
    }
    case 'reconcile': {
      if (!record.feature) throw new Error('A reconcile session needs a feature name')
      return {
        hooks: composeHooks(
          new ScopeGuard(workspaceRoot, reconcileScope(record.feature)),
          new SpecContract(workspaceRoot),
          new ScenarioContextContract(workspaceRoot, record.feature),
        ),
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, reconcilePrompt(record.feature, workspaceRoot)))),
        toolNames: RECONCILE_TOOLS,
      }
    }
    case 'cleanup': {
      if (!record.feature || !record.files) throw new Error('A cleanup session needs a feature name and the files to split')
      return {
        hooks: new ScopeGuard(workspaceRoot, cleanupScope(record.files)),
        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, cleanupPrompt(record.feature, workspaceRoot, ctx.cleanupLimits()))),
        toolNames: CLEANUP_TOOLS,
      }
    }
  }
}

